  select a.id, coalesce((select max(v.version_number) from assessment_versions v where v.assessment_id = a.id), 0) + 1, 'published'::assessment_status, (convert_from(decode('', 'base64'), 'UTF8'))::jsonb, now()
  from assessments a where a.slug = 'attention-control-test';
update assessments set current_version_id = (select v.id from assessment_versions v where v.assessment_id = assessments.id order by v.version_number desc limit 1) where slug = 'attention-control-test';
